    'confirm-switch': () => { const s = current(), target = activeModal.modelId, m = s.models.find(m => m.id === target); if ($('input[name="switch-mode"]:checked').value === 'close') { s.pendingModel = target; closePosition(s, '明确平仓并切换版本'); } else { s.pendingModel = target; if (m) m.frozen = true; log(s, 'MODEL', `候选 v${m?.version} 已冻结，等待当前持仓结束再切换。`); } closeModal(); save(); render(); toast(s.pendingModel ? '已安排版本切换：旧仓结束后生效。' : '已关闭虚拟持仓并切换模型。'); },
    train: startTraining, step,
    sma: () => { state.sma = !state.sma; save(); render(); }, markers: () => { state.markers = !state.markers; save(); render(); },
    'zoom-in': () => { state.zoom = Math.max(20, state.zoom - 12); save(); render(); }, 'zoom-out': () => { state.zoom = Math.min(100, state.zoom + 12); save(); render(); },
    'chart-reset': () => { state.zoom = 58; state.pan = 100; save(); render(); }, timeframe: () => toast('首版固定小时级闭合 K 线。分钟级执行与流式盘口留待后续开发。'),
    'toggle-outage': () => changeNews(state.newsStatus === 'outage' ? 'fresh' : 'outage'),
    'enable-news': () => { const s = current(); if (s.news) { route('training'); return; } if (!['BTC/USDT', 'ETH/USDT'].includes(s.symbol)) { toast('首批新闻因子仅覆盖 BTC / ETH。可创建相应品种的新策略。'); return; } if (s.status !== 'draft' || s.position || s.trades.length || s.orders.length || s.models.length || state.tasks.some(t => t.strategyId === s.id)) { toast('已有运行、模型或任务的配置保持冻结。请复制为新闻增强的新草稿，再重新训练。'); strategyForm('clone', { ...s, news: true }); } else { s.news = true; s.version++; log(s, 'CONFIG', '草稿已加入新闻因子，须重新训练。'); save(); route('training'); toast('已为草稿启用新闻因子。'); } },
    reset: () => openModal(modalShell('重置交互原型', '只影响当前浏览器中的 QuantPilot 原型状态。', '<div class="dialog-body"><p class="modal-copy">将删除你在此原型创建的策略、演示任务与交互记录，并恢复 BTC / ETH / SOL 三个初始样例。不会修改现有项目、数据库或回测结果。</p></div>', '<button data-action="close-modal">保留当前状态</button><button class="danger" data-action="confirm-reset">确认重置演示</button>'), { type: 'reset' }),
